static inline uint8_t ru_wave_band(uint32_t increment){
 if(increment>0x7fffffffu)return 0u;
 if(increment>0x3fffffffu)return 0u;
 if(increment>0x1fffffffu)return 1u;
 if(increment>0x0fffffffu)return 2u;
 if(increment>0x07ffffffu)return 3u;
 if(increment>0x03ffffffu)return 4u;
 if(increment>0x01ffffffu)return 5u;
 return 6u;
}
static inline int32_t ru_bandwave_level_read(uint8_t wave,uint8_t level,uint32_t phase){
 uint8_t index=(uint8_t)(phase>>24);
 uint32_t fraction=(phase>>16)&255u;
 const int16_t *t=(wave==RU_WAVE_SQUARE?ru_square_waves[level]:ru_saw_waves[level]);
 int32_t current=t[index];
 return current+(((int32_t)t[(uint8_t)(index+1u)]-current)*(int32_t)fraction>>8);
}
static inline int32_t ru_bandwave_read(uint8_t wave,uint32_t phase,uint32_t increment){
 uint8_t level=ru_wave_band(increment);
 int32_t now=ru_bandwave_level_read(wave,level,phase);
 if(level){
  /* Crossfade only BELOW the harmonic Nyquist threshold, over its lowest
   * 1/8 frequency band. No alias-prone harmonics above Nyquist. */
  uint32_t threshold=0x7fffffffu>>level;
  uint32_t fade_range=threshold>>3;
  if(increment>threshold-fade_range && increment<=threshold){
   uint32_t mix=(threshold-increment)>>(20u-level);
   if(mix>256u)mix=256u;
   int32_t previous=ru_bandwave_level_read(wave,(uint8_t)(level-1u),phase);
   now=((now*(int32_t)mix)+(previous*(int32_t)(256u-mix)))>>8;
  }
 }
 return now;
}
/* V1.48: Prevent high-frequency whistle from nonlinear SAW shaping.
 * The source tables are already bandlimited, but a heavily driven waveshaper
 * generates new harmonics which can fold back as audible alias tones.
 * At strong shaping levels, smoothly blend down to the existing 32- and
 * 16-partial tables BEFORE nonlinearity. This costs no new wavetable, state,
 * buffer, 64-bit math, division or sample-rate filter. At neutral settings
 * the exact original SAW PCM is returned. Suboscillator rendering is unchanged.
 * Parameter crossfades avoid clicks when turning the knobs. */
static inline uint8_t ru_saw_alias_strength(uint8_t bright,uint8_t edge,
 uint8_t shape_edge,uint8_t bite,uint8_t punch){
 uint32_t strength=0;
 /* Controls with meaningful timbre gain trigger the guard only in the
  * driven region. Values below these thresholds preserve original sound. */
 if(bright>75u)strength=(uint32_t)(bright-75u)*4u;
 if(edge>65u){uint32_t v=(uint32_t)(edge-65u)*3u;if(v>strength)strength=v;}
 if(shape_edge>65u){uint32_t v=(uint32_t)(shape_edge-65u)*3u;if(v>strength)strength=v;}
 if(bite>25u){uint32_t v=((uint32_t)bite-25u)*4u/3u;if(v>strength)strength=v;}
 if(punch>25u){uint32_t v=((uint32_t)punch-25u)*4u/3u;if(v>strength)strength=v;}
 return (uint8_t)(strength>100u?100u:strength);
}
static inline int32_t ru_saw_guarded_read(uint32_t phase,uint32_t increment,uint8_t strength){
 uint8_t band=ru_wave_band(increment);
 if(strength<=40u || band<=4u)return ru_bandwave_read(RU_WAVE_SAW,phase,increment);
 if(strength>=100u)return ru_bandwave_level_read(RU_WAVE_SAW,4u,phase);
 if(strength==70u && band>5u)return ru_bandwave_level_read(RU_WAVE_SAW,5u,phase);
 /* The selectable bands are never richer than the normal Nyquist-safe band.
  * Strength 40..70 fades to 32 partials; 70..100 fades to 16. */
 if(strength<=70u){
  if(band<=5u)return ru_bandwave_read(RU_WAVE_SAW,phase,increment);
  int32_t rich=ru_bandwave_read(RU_WAVE_SAW,phase,increment);
  int32_t quiet=ru_bandwave_level_read(RU_WAVE_SAW,5u,phase);
  uint32_t weight=((uint32_t)(strength-40u)*256u+15u)/30u;
  return rich+(((quiet-rich)*(int32_t)weight)>>8);
 }
 if(band<=5u){
  int32_t rich=ru_bandwave_read(RU_WAVE_SAW,phase,increment);
  int32_t quiet=ru_bandwave_level_read(RU_WAVE_SAW,4u,phase);
  uint32_t weight=((uint32_t)(strength-70u)*256u+15u)/30u;
  return rich+(((quiet-rich)*(int32_t)weight)>>8);
 }
 int32_t rich=ru_bandwave_level_read(RU_WAVE_SAW,5u,phase);
 int32_t quiet=ru_bandwave_level_read(RU_WAVE_SAW,4u,phase);
 uint32_t weight=((uint32_t)(strength-70u)*256u+15u)/30u;
 return rich+(((quiet-rich)*(int32_t)weight)>>8);
}

